import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

# Build lookup: project -> framework -> package -> version
def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                m[key] = pkg['resolvedVersion']
    return m

b = build_map(baseline)
a = build_map(after)

changes = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((key[0], key[1], key[2], bv, av))

if changes:
    print('CHANGES:')
    for proj, fw, pkg, old, new in changes:
        print(f'  {proj} ({fw}): {pkg} {old} -> {new}')
else:
    print('No changes - all versions identical')
"

